  figure: HTMLElement,
): void {
  const video = document.createElement("video");
  video.muted = true;
  video.loop = true;
  video.playsInline = true;
  video.preload = "none";
  figure.append(video);

  let isHovered = false;
  let pendingPlay: Promise<void> | null = null;

  const show = (): void => {
    if (!isHovered) return;
    video.style.opacity = "";
    figure.classList.add("is-video-active");
  };

  const hideVideoNow = (): void => {
    video.style.opacity = "0";
    figure.classList.remove("is-video-active");
  };

  const safePause = (): void => {
    video.pause();
    video.currentTime = 0;
  };

  const onEnter = (): void => {
    isHovered = true;
    video.style.opacity = "";
    if (!video.src) {
      video.src = videoUrl;
      video.load();
    }
    pendingPlay = video.play().catch(() => undefined);
    if (video.readyState >= 3) {
      show();
    } else {
      video.addEventListener("canplay", show, { once: true });
    }
  };

  const onLeave = (): void => {
    isHovered = false;
    video.removeEventListener("canplay", show);
    hideVideoNow();
    const p = pendingPlay;
    pendingPlay = null;
    if (p !== null) {
      void p.then(() => { if (!isHovered) safePause(); });
    } else {
      safePause();
    }
  };

  li.addEventListener("pointerenter", onEnter);
  li.addEventListener("pointerleave", onLeave);

  this._videoHoverCleanups.push(() => {
    isHovered = false;
    video.removeEventListener("canplay", show);
    figure.classList.remove("is-video-active");
    const p = pendingPlay;
    pendingPlay = null;
    if (p !== null) {
      void p.then(safePause);
    } else {
      safePause();
    }
    li.removeEventListener("pointerenter", onEnter);
    li.removeEventListener("pointerleave", onLeave);
  });
}

private _createModalButton(item: WorkApiItem): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className =
    "no-corner-btn no-works-canvas__grid-link js-work-modal-trigger";

