114	  async load(state: WorksPageState): Promise<WorkProjectItem[]> {
115	    this._fetchAbortController?.abort();
116	    this._fetchAbortController = new AbortController();
117	    const signal = this._fetchAbortController.signal;
118	    const projects: WorkProjectItem[] = [];
119	    let offset = 0;
120	    let hasMore = true;
121	
122	    while (hasMore && projects.length < WORK_CANVAS_CONFIG.totalCards) {
123	      const remaining = WORK_CANVAS_CONFIG.totalCards - projects.length;
124	      const response = await fetchWorksList(
125	        offset,
126	        Math.min(WORKS_LIST_API_MAX_LIMIT, remaining),
127	        state.category,
128	        signal,
129	      );
130	      response.items.forEach((item, index) => {
131	        projects.push(createWorkProjectItem(item, projects.length + index));
132	      });
133	      hasMore = response.hasMore;
134	      offset = response.nextOffset ?? offset + response.items.length;
135	      if (response.items.length === 0) {
136	        hasMore = false;
137	      }
138	    }
139	
140	    this._fetchAbortController = null;
141	    return projects;
142	  }
