&__bottom-toggle {
  z-index: var(--z-index-works-hud);
  display: flex;
  align-items: center;
  position: relative;
  min-width: fluid(164, 192);
  padding: 4px;
  pointer-events: auto;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--clr-white-100) 18%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--clr-black-100) 60%, transparent);
  backdrop-filter: blur(12px) saturate(140%);
  -webkit-backdrop-filter: blur(12px) saturate(140%);
  transition:
    opacity var(--transition-default),
    transform var(--transition-default);

  &[hidden],
  &[data-ready="false"] {
    opacity: 0;
    pointer-events: none;
    transform: translateX(-50%) translateY(20px);
  }

  &[data-ready="true"] {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }

  .no-works-canvas__toggle-rect {
    position: absolute;
    inset: 4px auto 4px 4px;
    width: calc(50% - 4px);
    border-radius: 999px;
    background: color-mix(in srgb, var(--clr-white-100) 12%, transparent);
    transition:
      transform var(--transition-default),
      background-color var(--transition-default);
    pointer-events: none;
    z-index: 0;
  }

  &[data-view="scatter"] .no-works-canvas__toggle-rect {
    transform: translateX(100%);
  }

  a,
  button {
    @include font("f-body-4");
    position: relative;
    z-index: 1;
    flex: 1 1 0;
    min-width: 0;
    font-family: var(--family-ui);
    letter-spacing: 0.04em;
    color: color-mix(in srgb, var(--clr-white-100) 56%, transparent);
    background: transparent;
    border: none;
    padding: 0.75rem 1rem;
    cursor: pointer;
    text-align: center;
    text-decoration: none;
    transition: color var(--transition-fast);

    &[aria-selected="true"],
    &.is-active {
      color: var(--clr-white-100);
    }

    &:hover {
      color: color-mix(in srgb, var(--clr-white-100) 84%, transparent);
    }
  }
}

&__bottom-controls {
  position: fixed;
  bottom: var(--gutter-xl);
  left: 50%;
  z-index: var(--z-index-works-hud);
  display: flex;
  align-items: center;
  gap: 0.75rem;
  transform: translateX(-50%);
  transition:
    opacity var(--transition-default),
    transform var(--transition-default);

  &[hidden],
  &[data-ready="false"] {
    opacity: 0;
    pointer-events: none;
    transform: translateX(-50%) translateY(20px);
  }

  &[data-ready="true"] {
    opacity: 1;
    transform: translateX(-50%) translateY(0);
  }
}

&__filter-wrap {
  position: relative;
  display: flex;
  align-items: center;
  pointer-events: auto;

  &[hidden],
  &.is-hidden,
  .no-works-canvas[data-view="grid"] & {
    display: none;
    pointer-events: none;
  }
}

&__filter-button {
  @include font("f-body-4");
  min-width: fluid(112, 144);
  display: inline-flex;

