private _syncViewAttributes(view: WorksViewMode): void {
  this._elements.root?.setAttribute("data-view", view);
  this._elements.toggle?.setAttribute("data-view", view);
  const gfw = this._elements.gridFilterWrap;
  if (gfw) {
    const isGrid = view === "grid";
    Aria.setHidden(gfw, !isGrid);
    if (isGrid) {
      gfw.removeAttribute("hidden");
      gfw.removeAttribute("inert");
    } else {
      gfw.setAttribute("hidden", "");
      gfw.setAttribute("inert", "");
    }
  }
}

